function circle(c,x,y,r,color){c.fillStyle=color;c.beginPath();c.arc(x,y,r,0,TAU);c.fill()}
function oval(c,x,y,rx,ry,color,rot=0){c.save();c.translate(x,y);c.rotate(rot);c.fillStyle=color;c.beginPath();c.ellipse(0,0,rx,ry,0,0,TAU);c.fill();c.restore()}
function lin(c,x,y,x2,y2,color,w=2){c.strokeStyle=color;c.lineWidth=w;c.beginPath();c.moveTo(x,y);c.lineTo(x2,y2);c.stroke()}
function grad(c,x,y,x2,y2,colors){let g=c.createLinearGradient(x,y,x2,y2);for(let i=0;i<colors.length;i++)g.addColorStop(i/(colors.length-1),colors[i]);return g}
function radial(c,x,y,r,col){let g=c.createRadialGradient(x,y,0,x,y,r);g.addColorStop(0,col);g.addColorStop(1,'transparent');c.fillStyle=g;c.fillRect(x-r,y-r,r*2,r*2)}
function poly(c,pts,col){c.fillStyle=col;c.beginPath();c.moveTo(...pts[0]);for(const p of pts.slice(1))c.lineTo(...p);c.closePath();c.fill()}
function strokePath(c,points,col,lw=2){c.strokeStyle=col;c.lineWidth=lw;c.beginPath();c.moveTo(...points[0]);for(const p of points.slice(1))c.lineTo(...p);c.stroke()}
function star(c,x,y,r,color){c.save();c.translate(x,y);c.rotate(Math.PI/4);c.fillStyle=color;c.beginPath();c.moveTo(0,-r);c.quadraticCurveTo(r*.1,-r*.1,r,0);c.quadraticCurveTo(r*.1,r*.1,0,r);c.quadraticCurveTo(-r*.1,r*.1,-r,0);c.quadraticCurveTo(-r*.1,-r*.1,0,-r);c.fill();c.restore()}
